import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { runInNewContext } from 'node:vm';
import { gzipSync } from 'node:zlib';

// Read only trusted manifests generated by this repository's `npm run build`.
const buildDir = process.argv[2] ?? '.next';
const routes = ['/', '/meals', '/meals/new', '/business', '/business/pricing', '/mypage'];
console.log('ページのclient-reference manifestに含まれるJSの合計。共通ランタイム等を含む実転送量やLCPではありません。');
console.log('| ページ | JS bytes | gzip bytes |');
console.log('|---|---:|---:|');
for (const route of routes) {
  const context = {};
  const manifestFile = join(buildDir, 'server/app', route === '/' ? '' : route.slice(1), 'page_client-reference-manifest.js');
  runInNewContext(readFileSync(manifestFile, 'utf8'), context);
  const manifests = Object.values(context.__RSC_MANIFEST);
  const chunks = new Set(manifests.flatMap(manifest => Object.values(manifest.clientModules)
    .flatMap(module => module.chunks).filter(chunk => chunk.endsWith('.js'))));
  let bytes = 0;
  let gzipBytes = 0;
  for (const chunk of chunks) {
    const content = readFileSync(join(buildDir, chunk));
    bytes += content.length;
    gzipBytes += gzipSync(content).length;
  }
  console.log(`| ${route} | ${bytes} | ${gzipBytes} |`);
}
